import{_ as a,o,c as r,ae as i}from"./chunks/framework.Dh1jimFm.js";const d=JSON.parse('{"title":"Superlookup Overview","description":"","frontmatter":{},"headers":[],"relativePath":"superlookup/overview.md","filePath":"superlookup/overview.md"}'),l={name:"superlookup/overview.md"};function t(s,e,n,c,u,h){return o(),r("div",null,e[0]||(e[0]=[i('<h1 id="superlookup-overview" tabindex="-1">Superlookup Overview <a class="header-anchor" href="#superlookup-overview" aria-label="Permalink to &quot;Superlookup Overview&quot;">​</a></h1><p>Superlookup is your unified concordance and research hub, bringing together all lookup resources in one place.</p><h2 id="opening-superlookup" tabindex="-1">Opening Superlookup <a class="header-anchor" href="#opening-superlookup" aria-label="Permalink to &quot;Opening Superlookup&quot;">​</a></h2><ul><li>Press <code>Ctrl+K</code> (opens Superlookup with the current selection, if any)</li><li>Or use <strong>Edit → Superlookup…</strong> (<code>Ctrl+Alt+L</code>)</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>On Windows, <code>Ctrl+Alt+L</code> can also work as a <strong>global hotkey</strong> (from any application) when AutoHotkey is installed.</p></div><p>Selected text is automatically used as the search query.</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><h3 id="tm-matches" tabindex="-1">TM Matches <a class="header-anchor" href="#tm-matches" aria-label="Permalink to &quot;TM Matches&quot;">​</a></h3><p>Search your Translation Memories for similar text:</p><ul><li>Fuzzy matching with percentage scores</li><li>Horizontal (table) or Vertical (list) view toggle</li><li>Source TM column shows which TM the match came from</li><li>Search direction: Both, Source only, or Target only</li></ul><h3 id="glossary-matches" tabindex="-1">Glossary Matches <a class="header-anchor" href="#glossary-matches" aria-label="Permalink to &quot;Glossary Matches&quot;">​</a></h3><p>Search your termbases/glossaries:</p><ul><li>Shows Source, Target, Domain, Notes columns</li><li>Right-click to &quot;Edit in Glossary&quot;</li><li>Direction and language filters (Both / Source / Target + From/To)</li></ul><h3 id="supermemory" tabindex="-1">Supermemory <a class="header-anchor" href="#supermemory" aria-label="Permalink to &quot;Supermemory&quot;">​</a></h3><p>Semantic search across all your TMs:</p><ul><li>Finds conceptually similar text (not just word matches)</li><li>Uses AI embeddings to understand meaning</li><li>Great for finding paraphrased or reworded content</li></ul><h3 id="machine-translation" tabindex="-1">Machine Translation <a class="header-anchor" href="#machine-translation" aria-label="Permalink to &quot;Machine Translation&quot;">​</a></h3><p>Get instant MT from multiple providers:</p><ul><li>Google Translate</li><li>DeepL</li><li>Microsoft Translator</li><li>Amazon Translate</li><li>MyMemory</li><li>ModernMT</li></ul><p>Configure providers in <strong>Settings → MT Settings</strong>.</p><h3 id="web-resources" tabindex="-1">Web Resources <a class="header-anchor" href="#web-resources" aria-label="Permalink to &quot;Web Resources&quot;">​</a></h3><p>Quick access to online reference sites:</p><ul><li>IATE (EU terminology)</li><li>Linguee</li><li>ProZ.com</li><li>Reverso Context</li><li>Wikipedia (Source &amp; Target)</li><li>Wiktionary (Source &amp; Target)</li><li>Google Search</li><li>Google Patents</li><li>Juremy</li><li>AcronymFinder</li><li>BabelNet</li><li>michaelbeijer.co.uk</li></ul><h2 id="search-controls" tabindex="-1">Search Controls <a class="header-anchor" href="#search-controls" aria-label="Permalink to &quot;Search Controls&quot;">​</a></h2><h3 id="language-filtering" tabindex="-1">Language Filtering <a class="header-anchor" href="#language-filtering" aria-label="Permalink to &quot;Language Filtering&quot;">​</a></h3><p>Use the <strong>From</strong> and <strong>To</strong> dropdowns to filter by language pair:</p><ul><li>Auto-populated from your TMs and termbases</li><li>Useful when you have multiple language pairs</li></ul><h3 id="search-direction" tabindex="-1">Search Direction <a class="header-anchor" href="#search-direction" aria-label="Permalink to &quot;Search Direction&quot;">​</a></h3><ul><li><strong>Both</strong>: Search in source AND target columns</li><li><strong>Source</strong>: Search only in source text</li><li><strong>Target</strong>: Search only in target text</li></ul><h3 id="search-box" tabindex="-1">Search Box <a class="header-anchor" href="#search-box" aria-label="Permalink to &quot;Search Box&quot;">​</a></h3><p>Type your query and press Enter (or click 🔍).</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><h3 id="copy-results" tabindex="-1">Copy Results <a class="header-anchor" href="#copy-results" aria-label="Permalink to &quot;Copy Results&quot;">​</a></h3><ul><li>Double-click a result to copy it</li><li>Or right-click for more options</li></ul><h3 id="persistent-sessions" tabindex="-1">Persistent Sessions <a class="header-anchor" href="#persistent-sessions" aria-label="Permalink to &quot;Persistent Sessions&quot;">​</a></h3><p>Web Resources tabs maintain login sessions, so you stay logged into sites like ProZ.com between searches.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./tm-search.html">TM Concordance Search</a></li><li><a href="./glossary-search.html">Glossary Search</a></li><li><a href="./mt.html">Machine Translation</a></li><li><a href="./web-resources.html">Web Resources</a></li></ul>',39)]))}const m=a(l,[["render",t]]);export{d as __pageData,m as default};
